// Sound effects for the course. Each name is a file in assets/sfx/ (generated by tools/make_assets.py).
// `play` throttles repeats so a ball rattling along a wall doesn't machine-gun the same clip.
const last = new Map();

export const sfx = {
    play(name, { volume = 1, pitch = 1, minGap = 0.07 } = {}) {
        const audio = window.Piston?.audio;
        if (!audio) return null;
        const now = performance.now() / 1000;
        if (now - (last.get(name) ?? -1) < minGap) return null;
        last.set(name, now);
        return audio.play(`./assets/sfx/${name}.wav`, { volume, pitch, bus: 'sfx' });
    },
};

export const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
